const c = outputs["read"].content;
const raw = c.basename || c.image || (Array.isArray(c.media) ? c.media[0] : '') || '';
const base = String(raw).split(/[\\/]/).pop();
if (!base) throw new Error('No receipt image path in job: ' + JSON.stringify(c));
return { basename: base, imageUrl: variables.engineBaseUrl + '/media/' + base };
